actions.script:
if (!ec.message.hasError()) {
    const verb = {move: 'Moved', assign: 'Assigned', lose: 'Closed as lost'}[batch] || 'Done'
    if (batchOut.successCount) ec.message.addMessage(verb + ' ' + batchOut.successCount + ' of ' + batchOut.results.length + ': '
            + batchOut.results.filter(row => row.ok).map(row => row.salesOpportunityId).join(', '), 'success')
    for (const row of batchOut.results.filter(row => !row.ok))
        ec.message.addMessage('Not done ' + row.salesOpportunityId + ': ' + String(row.message || '').replace(/^(Error: )?([A-Z_]+: )/, ''), 'warning')
}

service-call.in-map:
{salesOpportunityId:salesOpportunityId, expectedRevision:expectedRevision, competitorPartyId:competitorPartyId,
                        positionEnumId:(positionEnumId || null), strengths:(strengths || null), weaknesses:(weaknesses || null),
                        remove:(removeCompetitor == 'Y')}
